import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  const cleanupFns = [];

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const cardWidth = 2.4;
  const cardHeight = 1.5;

  const gradientMaterial = new MeshBasicNodeMaterial();
  const cardUv = uv();
  gradientMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.025, 0.025, 0.035),
      smoothstep(0.15, 0.95, cardUv.y)
    ),
    smoothstep(0.0, 1.0, cardUv.y)
  );

  const gradient = new Mesh(
    new PlaneGeometry(cardWidth, cardHeight),
    gradientMaterial
  );
  gradient.position.z = -0.02;
  root.add(gradient);
  resources.push(gradient.geometry, gradient.material);

  const imageMaterial = new MeshBasicNodeMaterial();
  imageMaterial.transparent = true;
  imageMaterial.opacity = 0.22;

  const image = new Mesh(
    new PlaneGeometry(cardWidth, cardHeight),
    imageMaterial
  );
  image.position.z = 0.005;
  root.add(image);
  resources.push(image.geometry, image.material);

  const frameMaterial = new MeshBasicNodeMaterial({ color: ink });
  const accentMaterial = new MeshBasicNodeMaterial({ color: accent });

  const frameParts = [
    [cardWidth, 0.035, 0, cardHeight * 0.5],
    [cardWidth, 0.035, 0, -cardHeight * 0.5],
    [0.035, cardHeight, -cardWidth * 0.5, 0],
    [0.035, cardHeight, cardWidth * 0.5, 0]
  ];

  for (const [width, height, x, y] of frameParts) {
    const part = new Mesh(new BoxGeometry(width, height, 0.035), frameMaterial);
    part.position.set(x, y, 0.025);
    root.add(part);
    resources.push(part.geometry);
  }
  resources.push(frameMaterial);

  const signalBar = new Mesh(
    new BoxGeometry(0.42, 0.045, 0.045),
    accentMaterial
  );
  signalBar.position.set(-cardWidth * 0.5 + 0.28, cardHeight * 0.5 - 0.24, 0.055);
  root.add(signalBar);
  resources.push(signalBar.geometry, accentMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textIndex = 0;

  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: paper,
      align: 'left',
      letterSpacingPx: item.role === 'label' ? 2 : 0
    });

    textObject.position.set(
      -cardWidth * 0.5 + 0.28,
      textIndex === 0 ? -0.08 : -0.28 - textIndex * 0.18,
      0.06
    );
    root.add(textObject);
    textIndex += 1;
  }

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      if (!loadedTexture) return;

      resources.push(loadedTexture);

      const region = config.atlasRegion ?? {
        x: 0,
        y: 0,
        width: 512,
        height: 320
      };

      const source = loadedTexture.image;
      const atlasWidth = source?.width || region.width;
      const atlasHeight = source?.height || region.height;

      const offsetX = region.x / atlasWidth;
      const offsetY = 1 - (region.y + region.height) / atlasHeight;
      const scaleX = region.width / atlasWidth;
      const scaleY = region.height / atlasHeight;

      const atlasCoordinates = uv()
        .mul(vec2(scaleX, scaleY))
        .add(vec2(offsetX, offsetY));

      imageMaterial.map = texture(loadedTexture, atlasCoordinates);
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const previousBeforeRender = root.onBeforeRender;
  root.onBeforeRender = (renderer, scene, camera) => {
    if (camera?.quaternion) root.quaternion.copy(camera.quaternion);
    if (previousBeforeRender) previousBeforeRender(renderer, scene, camera);
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (typeof result?.cleanup === 'function') cleanupFns.push(result.cleanup);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const cleanup of cleanupFns) cleanup();

    if (root.onBeforeRender) root.onBeforeRender = null;

    for (const resource of resources) {
      if (resource?.dispose) resource.dispose();
    }

    root.clear();
  };

  return root;
}

export default createNode;
